const body = $input.first().json.body;
// Thruuu envoie : { data: { eventType, id, reference, serps: [...] } }
const data = (body && body.data) ? body.data : body;
const serps = data.serps || [];
const processId = data.id || '';
const seedId = data.reference || '';
const now = new Date().toISOString().split('T')[0];

if (!serps.length) {
  return [{ json: { error: 'no_serps', process_id: processId, seed_id: seedId, raw: JSON.stringify(body).substring(0, 300) } }];
}

return serps.map(function(serp) {
  const topDomains = (serp.result || [])
    .slice(0, 5)
    .map(function(r) {
      return r.domain || (r.link || '').replace(/https?:\/\//, '').split('/')[0] || '';
    })
    .filter(Boolean)
    .join(', ');

  const similarQs = serp.similar_questions
    ? (Array.isArray(serp.similar_questions)
        ? serp.similar_questions.slice(0, 5)
        : Object.keys(serp.similar_questions).slice(0, 5)
      ).join(' / ')
    : '';

  const similarH = (serp.similar_headings || []).slice(0, 5).join(' / ');

  const relatedSearches = (serp.related_searches || [])
    .slice(0, 5)
    .map(function(r) { return typeof r === 'string' ? r : (r.query || ''); })
    .join(', ');

  const sv = serp.search_volume || {};
  const searchVolume = sv.volume !== undefined ? String(sv.volume) : JSON.stringify(sv);

  return {
    json: {
      thruuu_serp_id: serp.id || '',
      process_id: processId,
      seed_id: seedId,
      query: serp.query || '',
      device: serp.device || 'desktop',
      language: serp.hl || 'fr',
      country: serp.gl || 'fr',
      number_of_results: serp.number_of_results || 0,
      search_volume: searchVolume,
      top_domains: topDomains,
      similar_questions: similarQs,
      similar_headings: similarH,
      related_searches: relatedSearches,
      date_received: now
    }
  };
});
